// Generated by gen.py -- do not edit by hand.
// Case: fmin_s, CSR read at distance d = 8.
// mstatus.FS is set to Initial, the instruction under test is executed, then
// mstatus is read 8 instruction(s) later. PASS requires FS == 2'b11 (Dirty)
// and SD == 1.

    .option norvc
    .section .text.init, "ax"
    .globl _start

_start:
    // Trap handler: any trap is a test error, not a pass.
    la      x5, trap_entry
    csrw    mtvec, x5
    csrw    mstatus, x0             // FS = Off, MIE = 0
    li      x5, (1 << 13)           // FS = Initial so FP instructions decode
    csrs    mstatus, x5
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop

    // Operand setup. These instructions may dirty FS; FS is reset below.
    la x14, fp_a
    flw f1, 0(x14)
    flw f2, 4(x14)
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop

    // Force FS back to Initial (01) and SD to 0.
    li      x5, (3 << 13)
    csrc    mstatus, x5
    li      x5, (1 << 13)
    csrs    mstatus, x5
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop

    // ---- measurement window -------------------------------------------
    .balign 64
    fmin.s  f0, f1, f2
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    csrr    x10, mstatus
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    csrr    x19, mstatus
    // -------------------------------------------------------------------

    mv      x18, x10                // keep the observed mstatus for printing
    li      x7, 0x80006000
    and     x6, x10, x7
    and     x7, x19, x7
    bne     x6, x7, report_fail     // first read must equal the settled read
    srli    x6, x10, 13
    andi    x6, x6, 3
    li      x7, 3
    bne     x6, x7, report_fail     // FS must read Dirty
    srli    x6, x10, 31
    li      x7, 1
    bne     x6, x7, report_fail     // SD must read 1
    j       report_pass

trap_entry:
    csrr    x18, mcause
    la      x11, str_trap
    jal     x1, print_str
    mv      x10, x18
    jal     x1, print_hex
    la      x11, str_nl
    jal     x1, print_str
    j       report_fail

report_pass:
    la      x11, str_mstatus
    jal     x1, print_str
    mv      x10, x18
    jal     x1, print_hex
    la      x11, str_nl
    jal     x1, print_str
    la      x11, str_late
    jal     x1, print_str
    mv      x10, x19
    jal     x1, print_hex
    la      x11, str_nl
    jal     x1, print_str
    la      x11, str_pass
    jal     x1, print_str
    li      x1, 123456789
    li      x2, 0x20000000
    sw      x1, 0(x2)
    sw      x0, 4(x2)
self_loop_pass:
    j       self_loop_pass

report_fail:
    la      x11, str_mstatus
    jal     x1, print_str
    mv      x10, x18
    jal     x1, print_hex
    la      x11, str_nl
    jal     x1, print_str
    la      x11, str_late
    jal     x1, print_str
    mv      x10, x19
    jal     x1, print_hex
    la      x11, str_nl
    jal     x1, print_str
    la      x11, str_fail
    jal     x1, print_str
    li      x1, 1
    li      x2, 0x20000000
    sw      x1, 0(x2)
    sw      x1, 4(x2)
self_loop_fail:
    j       self_loop_fail

// x11 = NUL terminated string pointer
print_str:
    li      x28, 0x10000000
1:  lbu     x29, 0(x11)
    beq     x29, x0, 2f
    sw      x29, 0(x28)
    addi    x11, x11, 1
    j       1b
2:  jalr    x0, 0(x1)

// x10 = 32 bit value, printed as 8 hex digits
print_hex:
    li      x28, 0x10000000
    li      x30, 28
1:  srl     x29, x10, x30
    andi    x29, x29, 15
    li      x31, 10
    blt     x29, x31, 2f
    addi    x29, x29, 87            // 'a' - 10
    j       3f
2:  addi    x29, x29, 48            // '0'
3:  sw      x29, 0(x28)
    addi    x30, x30, -4
    bge     x30, x0, 1b
    jalr    x0, 0(x1)

    .section .rodata
    .balign 4
fp_a:
    .word   0x3f800000              // 1.0f
    .word   0x40000000              // 2.0f
    .word   0x3fc00000              // 1.5f  (inexact when converted to int)
    .word   0x7f800001              // signalling NaN
str_mstatus:
    .asciz  "RVCP: mstatus = 0x"
str_late:
    .asciz  "RVCP: mstatus (8 nops later) = 0x"
str_nl:
    .asciz  "\n"
str_trap:
    .asciz  "RVCP: UNEXPECTED TRAP, mcause = 0x"
str_pass:
    .asciz  "\nRVCP-SUMMARY: TEST PASSED - Test File \"fmin_s_d8.S\"\n\n"
str_fail:
    .asciz  "\nRVCP-SUMMARY: TEST FAILED - Test File \"fmin_s_d8.S\"\n\n"
